const colors=[['White','#f0eee3'],['Pink','#f49db4'],['Magenta','#e13fa7'],['Purple','#8f62db'],['Dark blue','#253b8e'],['Blue','#3978e7'],['Light blue','#7dc8ed'],['Light green','#8bcd83'],['Green','#429552'],['Dark green','#244a38'],['Beige','#d8c6a0'],['Light yellow','#f1e6a3'],['Yellow','#ecca42'],['Dark yellow','#bd941e'],['Orange','#e98a3b'],['Dark orange','#b3542e'],['Red','#dc5148'],['Dark red','#8f3438'],['Maroon','#63333b'],['Brown','#775139'],['Gray','#858b88'],['Black','#242728']];
const woods=[['Oak','#9b6c3e'],['Acacia','#b66d50'],['Pale oak','#cfb98e'],['Poplar','#b89c69'],['Cherry','#a95f5f'],['Dark oak','#4f382d'],['Pine','#a78350'],['Spruce','#74543b']];
const data=[];const add=(name,group,type,color='#92704f',extra={})=>data.push({name,group,type,color,...extra});
woods.forEach(([w,c])=>{[['Log','log'],['Wood wall','wall'],['Fence','fence'],['Slab','slab'],['Modern door','door'],['Planks','planks']].forEach(([n,t])=>add(`${w} ${n}`,'Wood',t,c,{species:w}));});
[['Limestone','#b7b3a5'],['Sandstone','#c5a77c'],['Slate','#626a6c'],['Basalt','#3d4244'],['Granite','#9a7668'],['Travertine','#c4b8a0']].forEach(([n,c])=>[['Block','block'],['Thick fence','fence'],['No-gap fence','solidfence'],['Slab','slab']].forEach(([s,t])=>add(`${n} ${s}`,'Stone',t,c)));
[['Carrara','#e7e2d7'],['Calacatta','#e8e2d6'],['Black marble','#292b2d'],['Green marble','#53695b'],['Rose marble','#ae7774'],['Onyx marble','#353536'],['Patterned marble','#aaa69d']].forEach(([n,c])=>[['Block','block'],['Full slab','slab'],['Thin slab','thinslab']].forEach(([s,t])=>add(`${n} ${s}`,'Marble',t,c,{pattern:n.includes('Patterned')||n==='Calacatta'})));
colors.forEach(([n,c])=>{[['LED stick','ledstick'],['LED plate','ledplate'],['LED circle','ledcircle'],['Glass block','glass'],['Glass pane','pane'],['Wool','wool'],['Concrete','block'],['Lamp','lamp'],['Light bulb','bulb']].forEach(([s,t])=>add(`${n} ${s}`,'Lighting & color',t,c,{glow:t.startsWith('led')||t==='bulb'||t==='lamp'}));});
[['Modern wall light','walllamp','#e8e8ce'],['Ceiling panel','ledplate','#e8e8ce'],['Garden bollard','ledstick','#d9e8ca'],['Clear glass','glass','#c4e7df'],['Frosted glass','pane','#d9e7df']].forEach(([n,t,c])=>add(n,'Lighting & color',t,c,{glow:t.includes('led')||t.includes('lamp')}));
[['Glock display','prop','#31383a'],['AR display','prop','#39403b'],['AK display','prop','#66533c'],['SMG display','prop','#343a3b'],['Minigun display','prop','#48504e'],['Plasma pistol · prop','plasma','#4a67bf'],['Plasma AR · prop','plasma','#5473b9'],['Plasma AK · prop','plasma','#69599c'],['Plasma SMG · prop','plasma','#477b9a'],['Plasma minigun · prop','plasma','#586baa']].forEach(([n,t,c])=>add(n,'Props',t,c,{note:'Display only'}));
[['Hardwood bench','bench','#79583c'],['Stone planter','planter','#8a8d83'],['Street tree','tree','#567e53'],['Road tile','road','#353a38'],['Grass block','block','#668858'],['Water feature','water','#527f82'],['Window panel','pane','#9dd6d5']].forEach(([n,t,c])=>add(n,'Props',t,c));
const categoryList=['All','Wood','Stone','Marble','Lighting & color','Props'];let activeCategory='All',selected=data.find(x=>x.name==='Oak Planks')||data[5],placed=[],day=true;
const iconSvg=(item)=>{let c=item.color;let shape=item.type==='ledcircle'||item.type==='bulb'?'circle':item.type==='log'||item.type==='ledstick'?'stick':item.type==='fence'||item.type==='solidfence'?'fence':item.type==='door'?'door':'block';let fill=shape==='circle'?`<circle cx="24" cy="24" r="13" fill="${c}"/>`:shape==='stick'?`<rect x="19" y="7" width="10" height="34" rx="5" fill="${c}"/>`:shape==='fence'?`<path d="M8 16h32M8 32h32M12 12v25m12-25v25m12-25v25" stroke="${c}" stroke-width="5" stroke-linecap="round"/>`:shape==='door'?`<rect x="12" y="5" width="24" height="36" rx="2" fill="${c}"/><circle cx="31" cy="24" r="1.7" fill="#e6dfc7"/>`:`<path d="M9 13 24 6l15 7-15 8z" fill="${c}"/><path d="M9 13v17l15 8V21z" fill="${c}"/><path d="M24 21v17l15-8V13z" fill="${c}"/>`;return `<svg viewBox="0 0 48 48" aria-hidden="true">${fill}</svg>`};
const itemCount=document.getElementById('itemCount'),inventory=document.getElementById('inventory'),categories=document.getElementById('categories'),search=document.getElementById('search');
function renderCategories(){categories.innerHTML=categoryList.map(c=>`<button class="cat ${c===activeCategory?'active':''}" data-cat="${c}">${c}</button>`).join('');categories.querySelectorAll('.cat').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.cat;renderCategories();renderInventory()})}
function renderInventory(){const q=search.value.toLowerCase();let filtered=data.filter(x=>(activeCategory==='All'||x.group===activeCategory)&&x.name.toLowerCase().includes(q));itemCount.textContent=`${filtered.length} ITEMS`;let grouped={};filtered.forEach(x=>(grouped[x.group]??=[]).push(x));inventory.innerHTML=Object.entries(grouped).map(([group,items])=>`<section class="invsection">${group.toUpperCase()}</section><div class="items">${items.map(x=>`<button class="item ${selected===x?'selected':''}" data-name="${x.name}"><span class="swatch" style="background:linear-gradient(145deg,${x.color}66,#151a17)">${iconSvg(x)}</span><span class="itemname">${x.name}</span><span class="itemsub">${x.note||group}</span></button>`).join('')}</div>`).join('')||'<div style="font-size:11px;color:#99a496;padding:20px">No matching materials.</div>';inventory.querySelectorAll('.item').forEach(b=>b.onclick=()=>selectItem(data.find(x=>x.name===b.dataset.name)));}
function selectItem(item){selected=item;document.getElementById('selectedName').textContent=item.name;document.querySelectorAll('.item').forEach(b=>b.classList.toggle('selected',b.dataset.name===item.name));document.getElementById('modeLabel').textContent=item.type==='prop'||item.type==='plasma'?'DISPLAY':'PLACE';if(innerWidth<850)document.getElementById('panel').classList.remove('open');toast(`${item.name} selected`);}
search.oninput=renderInventory;renderCategories();renderInventory();
const hotbar=document.getElementById('hotbar');const hotItems=['Oak Planks','Limestone Block','Carrara Full slab','White LED stick','White Glass block','White Lamp'];hotbar.innerHTML=hotItems.map((n,i)=>{let x=data.find(z=>z.name===n)||data[i];return `<button class="hot ${i===0?'active':''}" data-name="${x.name}" title="${x.name}"><span class="slotnum">${i+1}</span>${iconSvg(x)}</button>`}).join('');hotbar.querySelectorAll('.hot').forEach((b,i)=>b.onclick=()=>{hotbar.querySelectorAll('.hot').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectItem(data.find(x=>x.name===b.dataset.name))});
search.closest('.search').addEventListener('click',()=>{});document.getElementById('paneltoggle').onclick=()=>document.getElementById('panel').classList.toggle('open');
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1400)}

const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5bd');scene.fog=new THREE.FogExp2('#a9c5bd',.0028);
const camera=new THREE.PerspectiveCamera(43,innerWidth/innerHeight,.1,550);camera.position.set(44,40,47);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.outputColorSpace=THREE.SRGBColorSpace;document.getElementById('scene').appendChild(renderer.domElement);
const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,0,0);controls.enableDamping=true;controls.dampingFactor=.07;controls.maxPolarAngle=Math.PI*.47;controls.minDistance=15;controls.maxDistance=115;controls.mouseButtons={LEFT:THREE.MOUSE.PAN,MIDDLE:THREE.MOUSE.DOLLY,RIGHT:THREE.MOUSE.ROTATE};controls.touches={ONE:THREE.TOUCH.ROTATE,TWO:THREE.TOUCH.DOLLY_PAN};
scene.add(new THREE.HemisphereLight('#e5f1dc','#526044',2.1));let sun=new THREE.DirectionalLight('#fff0ce',3.3);sun.position.set(-38,62,28);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-90;sun.shadow.camera.right=90;sun.shadow.camera.top=90;sun.shadow.camera.bottom=-90;sun.shadow.bias=-.00015;scene.add(sun);
const mat=(color,rough=.82,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const ground=new THREE.Mesh(new THREE.PlaneGeometry(260,260),mat('#728b61'));ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
function box(parent,x,y,z,w,h,d,color,opts={}){let m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color,opts.rough??.82,opts.metal??0));m.position.set(x,y,z);m.castShadow=opts.shadow!==false;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,color,sy=1){let m=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),mat(color));m.scale.y=sy;m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,color,segments=8){let m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat(color));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function flat(parent,x,z,w,d,color,y=.01){let m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),mat(color,1));m.rotation.x=-Math.PI/2;m.position.set(x,y,z);m.receiveShadow=true;parent.add(m);return m}
// Soft sculpted valley, meadow patches and a reflective river winding through the north.
flat(scene,0,-36,245,30,'#819369',-.075);flat(scene,0,36,245,32,'#7d8f63',-.074);flat(scene,-42,0,28,200,'#788d5e',-.073);flat(scene,47,0,34,205,'#83966a',-.072);
const river=new THREE.Mesh(new THREE.PlaneGeometry(12,180),new THREE.MeshPhysicalMaterial({color:'#668e8d',roughness:.22,metalness:.08,transparent:true,opacity:.91}));river.rotation.x=-Math.PI/2;river.rotation.z=-.29;river.position.set(-59,.01,-18);scene.add(river);
// distant layered hills
for(let i=0;i<18;i++){let x=-105+i*13;let h=12+Math.sin(i*2.7)*7+Math.random()*5;let m=new THREE.Mesh(new THREE.ConeGeometry(19,h,6),mat(i%2?'#71876b':'#819177'));m.position.set(x,h*.43,-103+(i%3)*7);m.scale.z=.72;m.receiveShadow=true;scene.add(m)}
// Highways, shoulders, lane markings and ramps
function road(x,z,w,d,rot=0){let g=new THREE.Group();g.position.set(x,.04,z);g.rotation.y=rot;scene.add(g);let base=new THREE.Mesh(new THREE.BoxGeometry(w,.15,d),mat('#555b57',.92));base.position.y=.02;base.receiveShadow=true;g.add(base);let edge=mat('#d4cda9',.7);for(let side of [-1,1]){let e=new THREE.Mesh(new THREE.BoxGeometry(w,.03,.18),edge);e.position.set(0,.11,side*(d/2-1.0));g.add(e)}for(let i=-Math.floor(w/5);i<=Math.floor(w/5);i++){let dash=new THREE.Mesh(new THREE.BoxGeometry(2.2,.025,.13),mat('#ede0a9',.8));dash.position.set(i*5,.112,0);g.add(dash)}return g}
road(0,-36,230,8,.02);road(39,1,145,7,Math.PI/2);road(18,-30,65,4,-.17);road(-15,-12,56,4,Math.PI/2);road(58,-33,62,3,-.24);
// City neighborhood: custom varied architecture with window bands, rooftop trim and street trees.
const buildingColors=['#b8b2a1','#c4b8a4','#8e9b91','#d4c7b1','#8a938c','#c9c4b6'];
function building(x,z,w,d,h,idx){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let color=buildingColors[idx%buildingColors.length];box(g,0,h/2,0,w,h,d,color);box(g,0,h+.25,0,w+.45,.45,d+.45,idx%3===0?'#555c54':'#817c6c');let floors=Math.max(2,Math.floor(h/3.3));for(let f=0;f<floors;f++){let y=1.15+f*3.1;for(let side of [-1,1])for(let xx=-w/2+1.4;xx<w/2-.6;xx+=2.6){box(g,xx,y,side*(d/2+.015),.92,1.25,.06,idx%4===0?'#74908d':'#637e7e',{rough:.35,metal:.15});box(g,side*(w/2+.015),y,xx,.06,1.2,.92,'#657c7a',{rough:.35,metal:.12})}}if(idx%3===0){box(g,0,h+.58,0,w*.35,.35,d*.35,'#9b8e77');}return g}
let bi=0;for(let rz=0;rz<4;rz++)for(let rx=0;rx<5;rx++){let x=22+rx*12+(rz%2)*2,z=-8+rz*12;if(Math.abs(z+36)<8||Math.abs(x-39)<6)continue;building(x,z,7+((rx+rz)%3),6+((rx*2+rz)%3),7+((rx*3+rz*2)%4)*2,bi++)}
// Street trees and meadow woodland clusters
function tree(x,z,s=1,autumn=false){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,0,1.25*s,0,.24*s,.34*s,2.5*s,autumn?'#73533c':'#73573d');let palette=autumn?['#a67850','#b98b55','#8d7449']:['#496d4a','#5b7950','#6f8653'];for(let i=0;i<3;i++){let r=(1.15-i*.18)*s;let crown=new THREE.Mesh(new THREE.IcosahedronGeometry(r,1),mat(palette[i]));crown.position.set((i-1)*.18*s,(2.5+i*.62)*s,(i%2-.5)*.24*s);crown.scale.set(1,1.2,.94);crown.castShadow=true;g.add(crown)}return g}
for(let i=0;i<100;i++){let x=(Math.random()-.5)*190,z=(Math.random()-.5)*160;if((Math.abs(x)<20&&Math.abs(z)<18)||(Math.abs(z+36)<8)||(Math.abs(x-39)<8)||x<-45)continue;tree(x,z,.65+Math.random()*.75,Math.random()<.14)}
for(let i=0;i<16;i++)tree(-38+Math.random()*18,-25+Math.random()*63,.8+Math.random()*.7);
// Wild grasses and small ornamental meadow detail, sparse for mobile performance.
for(let i=0;i<105;i++){let x=(Math.random()-.5)*92,z=(Math.random()-.5)*80;if(Math.abs(x)<13&&Math.abs(z)<12)continue;let stem=new THREE.Mesh(new THREE.ConeGeometry(.15,.55,4),mat(i%2?'#9b9b66':'#b2a66c'));stem.position.set(x,.25,z);stem.castShadow=false;scene.add(stem)}
// A small homestead and glass greenhouse provide a recognizable build destination.
building(-8,7,10,9,7,4);let house=scene.children[scene.children.length-1];box(house,0,7.4,0,11,.6,10,'#4e5048');
for(let z of [-5,5]){box(scene,-20,1.3,z,.18,2,.18,'#635847');let orb=sphere(scene,-20,2.5,z,.42,'#e6d9a8');}
const grid=new THREE.GridHelper(100,50,'#ffffff27','#ffffff16');grid.position.y=.012;grid.material.transparent=true;grid.material.opacity=.26;scene.add(grid);
// Build palette material helper. The surface variations remain simple and tactile for responsive play.
const placedRoot=new THREE.Group();scene.add(placedRoot);const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let hoverMesh=null;
function makeBuild(item,x,z){let g=new THREE.Group();g.position.set(x,0,z);placedRoot.add(g);const c=item.color;const type=item.type;
if(type==='log'){cylinder(g,0,.55,0,.47,.47,1.1,c,12).rotation.x=Math.PI/2;let end=new THREE.Mesh(new THREE.CircleGeometry(.43,12),mat('#c5a27c'));end.rotation.y=Math.PI/2;end.position.set(.56,.55,0);g.add(end)}
else if(type==='slab'||type==='thinslab'){box(g,0,type==='thinslab'?.12:.25,0,1.9,type==='thinslab'?.24:.5,1.9,c,{rough:.76});if(item.pattern){for(let i=0;i<4;i++){let line=box(g,(i-1.5)*.35,.38,0,.035,.01,1.9,'#786e63',{shadow:false});line.material.transparent=true;line.material.opacity=.5}}}
else if(type==='fence'||type==='solidfence'){if(type==='solidfence')box(g,0,.72,0,1.8,1.44,.42,c);else{for(let x of [-.7,.7])box(g,x,.55,0,.19,1.1,.22,c);for(let y of [.34,.78])box(g,0,y,0,1.7,.18,.2,c);if(item.group==='Wood')for(let x of [-.3,0,.3])box(g,x,.54,0,.13,.86,.16,c)}}
else if(type==='door'){box(g,0,1,0,1.45,2,.16,c);box(g,.48,1,.1,.07,.07,.04,'#d7c78c')}
else if(type==='wall'){box(g,0,.85,0,1.9,1.7,.24,c);if(item.group==='Wood')for(let y=.4;y<1.6;y+=.28)box(g,0,y,.13,1.87,.035,.025,'#ffffff33')}
else if(type==='ledstick'){box(g,0,.8,0,.23,1.6,.24,c,{rough:.28,metal:.1});box(g,0,.8,.14,.12,1.4,.03,'#fff5dc',{rough:.24})}
else if(type==='ledplate'){box(g,0,.16,0,1.75,.28,1.2,c,{rough:.25,metal:.1});box(g,0,.31,0,1.52,.045,1,'#fff8df',{rough:.2})}
else if(type==='ledcircle'||type==='bulb'||type==='lamp'||type==='walllamp'){if(type==='walllamp')box(g,0,.9,-.35,.65,.38,.28,'#393d39');if(type==='lamp')cylinder(g,0,.15,0,.32,.32,.3,'#454945');let bulb=new THREE.Mesh(new THREE.SphereGeometry(type==='bulb'?.3:.43,18,14),new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:1.55,roughness:.28}));bulb.position.y=type==='lamp'?.78:type==='walllamp'?1.1:.48;g.add(bulb);if(type==='lamp')cylinder(g,0,.53,0,.07,.07,.52,'#d5d0be');if(type==='bulb')cylinder(g,0,.12,0,.12,.1,.2,'#b4a995');if(placed.length<25){let p=new THREE.PointLight(c,1.2,5);p.position.y=1;g.add(p)}}
else if(type==='glass'||type==='pane'){let m=new THREE.Mesh(new THREE.BoxGeometry(type==='pane'?1.85:1.55,type==='pane'?1.5:1.5,type==='pane'?.12:1.3),new THREE.MeshPhysicalMaterial({color:c,roughness:.17,metalness:.04,transmission:.36,transparent:true,opacity:.58,thickness:.15}));m.position.y=.8;g.add(m);if(type==='pane'){box(g,0,.8,-.08,1.9,1.55,.09,'#e6eee0',{rough:.38,metal:.3});}}
else if(type==='prop'||type==='plasma'){let plasma=type==='plasma';let body=box(g,0,.52,0,plasma?1.1:1.05,.23,.27,c,{rough:.35,metal:.35});body.rotation.y=-.15;box(g,-.15,.3,0,.24,.42,.3,plasma?'#77caff':'#252a27',{rough:.42,metal:.3});box(g,.32,.66,0,.4,.1,.17,plasma?'#52d3ff':'#737976',{rough:.35,metal:.4});if(plasma){let orb=sphere(g,.54,.52,0,.18,'#58d8ff');orb.material.emissive=new THREE.Color('#159eff');orb.material.emissiveIntensity=1.8}g.rotation.y=Math.PI/2;}
else if(type==='bench'){box(g,0,.64,0,1.7,.18,.65,c);for(let x of [-.62,.62])box(g,x,.3,0,.12,.6,.58,'#414943');for(let y of [1.02,1.35])box(g,0,y,-.28,1.7,.1,.12,c)}
else if(type==='planter'){box(g,0,.38,0,1.5,.75,1.1,c);box(g,0,.79,0,1.25,.05,.85,'#554b3b');for(let i=0;i<4;i++){let b=sphere(g,(i-1.5)*.25,1.08,(i%2)*.24-.12,.33,'#65845a',1.45)}}
else if(type==='tree'){tree(x,z,.78,true);return g}
else if(type==='road'){box(g,0,.04,0,2,.08,2,c)}
else if(type==='water'){let m=new THREE.Mesh(new THREE.BoxGeometry(1.9,.12,1.9),new THREE.MeshPhysicalMaterial({color:c,roughness:.12,metalness:.16,transparent:true,opacity:.86}));m.position.y=.05;g.add(m)}
else {box(g,0,.5,0,1.8,1,1.8,c,{rough:item.group==='Marble'?.28:.82,metal:item.group==='Marble'?.08:0});if(item.pattern){for(let j=0;j<3;j++){let seam=box(g,0,.99,-.48+j*.48,1.8,.012,.018,'#5d5751',{shadow:false});seam.material.transparent=true;seam.material.opacity=.55}}}
return g}
function placeAt(clientX,clientY,remove=false){let r=renderer.domElement.getBoundingClientRect();pointer.x=(clientX-r.left)/r.width*2-1;pointer.y=-((clientY-r.top)/r.height)*2+1;raycaster.setFromCamera(pointer,camera);let groundHit=raycaster.intersectObject(ground);if(!groundHit.length)return;let p=groundHit[0].point;let x=Math.round(p.x/2)*2,z=Math.round(p.z/2)*2;if(Math.abs(x)>100||Math.abs(z)>100)return;if(remove){let nearest=null,dist=2.2;placed.forEach(o=>{let d=Math.hypot(o.position.x-x,o.position.z-z);if(d<dist){dist=d;nearest=o}});if(nearest){placedRoot.remove(nearest);placed.splice(placed.indexOf(nearest),1);document.getElementById('placedCount').textContent=placed.length;toast('Piece removed')}return}let obj=makeBuild(selected,x,z);placed.push(obj);document.getElementById('placedCount').textContent=placed.length;document.getElementById('selectedHint').textContent='TAP WORLD TO PLACE';if(placed.length===1)document.getElementById('hintpill').textContent='Nice start — build a home, light it up, make it yours';}

else if(type==='tree'){cylinder(g,0,.9,0,.16,.22,1.8,'#73573d');for(let i=0;i<3;i++){let crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.66-i*.09,1),mat(i===1?'#648254':'#54784f'));crown.position.set(0,1.7+i*.42,0);crown.scale.set(1,1.22,.95);crown.castShadow=true;g.add(crown)}}
return g}
