[['Carrara','#e7e2d7'],['Calacatta','#e8e2d6'],['Black marble','#292b2d'],['Green marble','#53695b'],['Rose marble','#ae7774'],['Onyx marble','#353536'],['Patterned marble','#aaa69d']].forEach(([n,c])=>[['Block','block'],['Full slab','slab'],['Thin slab','thinslab']].forEach(([s,t])=>add(`${n} ${s}`,'Marble',t,c,{pattern:n.includes('Patterned')||n==='Calacatta'})));
colors.forEach(([n,c])=>[['LED stick','ledstick'],['LED plate','ledplate'],['LED circle','ledcircle'],['Glass block','glass'],['Glass pane','pane'],['Wool','wool'],['Concrete','block'],['Lamp','lamp'],['Light bulb','bulb']].forEach(([s,t])=>add(`${n} ${s}`,'Lighting & color',t,c,{glow:t.startsWith('led')||t==='bulb'||t==='lamp'})));
[['Modern wall light','walllamp','#e8e8ce'],['Clear glass','glass','#c4e7df'],['Frosted glass','pane','#d9e7df']].forEach(([n,t,c])=>add(n,'Lighting & color',t,c,{glow:t.includes('led')||t.includes('lamp')}));
[['Glock display','prop','#31383a'],['AR display','prop','#39403b'],['AK display','prop','#66533c'],['SMG display','prop','#343a3b'],['Minigun display','prop','#48504e'],['Plasma pistol · prop','plasma','#4a67bf'],['Plasma AR · prop','plasma','#5473b9'],['Plasma AK · prop','plasma','#69599c'],['Plasma SMG · prop','plasma','#477b9a'],['Plasma minigun · prop','plasma','#586baa']].forEach(([n,t,c])=>add(n,'Props',t,c,{note:'Display only'}));
[['Hardwood bench','bench','#79583c'],['Stone planter','planter','#8a8d83'],['Street tree','tree','#567e53'],['Road tile','road','#353a38'],['Grass block','block','#668858'],['Water feature','water','#527f82'],['Window panel','pane','#9dd6d5']].forEach(([n,t,c])=>add(n,'Props',t,c));
const categoryList=['All','Wood','Stone','Marble','Lighting & color','Props'];let activeCategory='All',selected=data.find(x=>x.name==='Oak Planks'),placed=[],day=true;
