const itemCount=document.getElementById('itemCount'),inventory=document.getElementById('inventory'),categories=document.getElementById('categories'),search=document.getElementById('search');
function renderCategories(){categories.innerHTML=categoryList.map(c=>`<button class="cat ${c===activeCategory?'active':''}" data-cat="${c}">${c}</button>`).join('');categories.querySelectorAll('.cat').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.cat;renderCategories();renderInventory()})}
function renderInventory(){const q=search.value.toLowerCase(),filtered=data.filter(x=>(activeCategory==='All'||x.group===activeCategory)&&x.name.toLowerCase().includes(q));itemCount.textContent=`${filtered.length} ITEMS`;let grouped={};filtered.forEach(x=>(grouped[x.group]??=[]).push(x));inventory.innerHTML=Object.entries(grouped).map(([group,items])=>`<section class="invsection">${group.toUpperCase()}</section><div class="items">${items.map(x=>`<button class="item ${selected===x?'selected':''}" data-name="${x.name}"><span class="swatch" style="background:linear-gradient(145deg,${x.color}66,#151a17)">${iconSvg(x)}</span><span class="itemname">${x.name}</span><span class="itemsub">${x.note||group}</span></button>`).join('')}</div>`).join('')||'<div style="font-size:11px;color:#99a496;padding:20px">No matching materials.</div>';inventory.querySelectorAll('.item').forEach(b=>b.onclick=()=>selectItem(data.find(x=>x.name===b.dataset.name)))}
